CREATE TABLE public.notification_preferences (user_id uuid PRIMARY KEY, enabled boolean NOT NULL DEFAULT true, additions boolean NOT NULL DEFAULT true, online boolean NOT NULL DEFAULT true, online_cooldown_minutes integer NOT NULL DEFAULT 15 CHECK (online_cooldown_minutes IN (5,15,30,60)), last_online_notice timestamptz);
GRANT SELECT, INSERT, UPDATE ON public.notification_preferences TO authenticated;
GRANT ALL ON public.notification_preferences TO service_role;
ALTER TABLE public.notification_preferences ENABLE ROW LEVEL SECURITY;
CREATE POLICY preferences_read ON public.notification_preferences FOR SELECT TO authenticated USING (user_id = auth.uid() AND public.is_duet_member());
CREATE POLICY preferences_insert ON public.notification_preferences FOR INSERT TO authenticated WITH CHECK (user_id = auth.uid() AND public.is_duet_member());
CREATE POLICY preferences_update ON public.notification_preferences FOR UPDATE TO authenticated USING (user_id = auth.uid() AND public.is_duet_member()) WITH CHECK (user_id = auth.uid() AND public.is_duet_member());
REVOKE UPDATE ON public.notification_preferences FROM authenticated;
GRANT UPDATE(enabled, additions, online, online_cooldown_minutes) ON public.notification_preferences TO authenticated;
CREATE TABLE public.push_event_queue (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL, recipient_id uuid NOT NULL, kind text NOT NULL, body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz);
GRANT ALL ON public.push_event_queue TO service_role;
ALTER TABLE public.push_event_queue ENABLE ROW LEVEL SECURITY;
CREATE INDEX push_event_pending ON public.push_event_queue(created_at) WHERE processed_at IS NULL;
CREATE TABLE public.duet_presence (user_id uuid PRIMARY KEY, last_seen timestamptz NOT NULL);
GRANT ALL ON public.duet_presence TO service_role;
ALTER TABLE public.duet_presence ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.enqueue_duet_push(actor uuid, event_kind text, event_body text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ INSERT INTO public.push_event_queue(actor_id,recipient_id,kind,body) SELECT actor,user_id,event_kind,left(event_body,200) FROM public.couple_members WHERE user_id <> actor AND EXISTS(SELECT 1 FROM public.couple_members WHERE user_id = actor) $$;
REVOKE ALL ON FUNCTION public.enqueue_duet_push(uuid,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.enqueue_duet_push(uuid,text,text) TO service_role;
CREATE FUNCTION public.queue_duet_addition() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE actor uuid; msg text; BEGIN actor := auth.uid(); IF TG_TABLE_NAME = 'records' THEN msg := CASE NEW.kind WHEN 'music' THEN 'adicionou uma música' WHEN 'goal' THEN 'adicionou uma meta' WHEN 'task' THEN 'adicionou um próximo passo' WHEN 'setting' THEN 'definiu a data do casamento' ELSE 'adicionou uma anotação' END || ': ' || NEW.title; ELSIF TG_TABLE_NAME = 'references_catalog' THEN msg := 'adicionou uma referência: ' || NEW.title; ELSIF TG_TABLE_NAME = 'messages' THEN msg := 'enviou uma mensagem no chat'; ELSIF TG_TABLE_NAME = 'profiles' THEN IF NEW.avatar_path IS NOT DISTINCT FROM OLD.avatar_path THEN RETURN NEW; END IF; msg := 'adicionou uma nova foto de perfil'; END IF; PERFORM public.enqueue_duet_push(actor,'addition',msg); RETURN NEW; END $$;
CREATE TRIGGER records_push_add AFTER INSERT ON public.records FOR EACH ROW EXECUTE FUNCTION public.queue_duet_addition();
CREATE TRIGGER references_push_add AFTER INSERT ON public.references_catalog FOR EACH ROW EXECUTE FUNCTION public.queue_duet_addition();
CREATE TRIGGER messages_push_add AFTER INSERT ON public.messages FOR EACH ROW EXECUTE FUNCTION public.queue_duet_addition();
CREATE TRIGGER avatar_push_add AFTER UPDATE OF avatar_path ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.queue_duet_addition();
CREATE FUNCTION public.queue_duet_update() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.entity_type IN ('votes','signatures') OR (NEW.entity_type = 'records' AND NEW.action <> 'INSERT') THEN PERFORM public.enqueue_duet_push(NEW.actor_id,'update',CASE NEW.entity_type WHEN 'votes' THEN 'avaliou uma referência no Dream Match' WHEN 'signatures' THEN 'assinou uma meta' ELSE 'atualizou os planos de vocês' END); END IF; RETURN NEW; END $$;
CREATE TRIGGER activity_push_update AFTER INSERT ON public.activity FOR EACH ROW EXECUTE FUNCTION public.queue_duet_update();
CREATE FUNCTION public.heartbeat_duet_push(actor uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE transitioned boolean; BEGIN INSERT INTO public.duet_presence(user_id,last_seen) VALUES(actor,now()) ON CONFLICT(user_id) DO UPDATE SET last_seen = excluded.last_seen WHERE duet_presence.last_seen < now() - interval '90 seconds' RETURNING true INTO transitioned; IF transitioned THEN PERFORM public.enqueue_duet_push(actor,'online','ficou online no Duet ♡'); ELSE UPDATE public.duet_presence SET last_seen = now() WHERE user_id = actor; END IF; RETURN COALESCE(transitioned,false); END $$;
REVOKE ALL ON FUNCTION public.heartbeat_duet_push(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.heartbeat_duet_push(uuid) TO service_role;
CREATE FUNCTION public.claim_duet_push_events() RETURNS SETOF public.push_event_queue LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE e public.push_event_queue; p public.notification_preferences; BEGIN FOR e IN SELECT * FROM public.push_event_queue WHERE processed_at IS NULL ORDER BY created_at LIMIT 100 FOR UPDATE SKIP LOCKED LOOP UPDATE public.push_event_queue SET processed_at = now() WHERE id = e.id; INSERT INTO public.notification_preferences(user_id) VALUES(e.recipient_id) ON CONFLICT DO NOTHING; SELECT * INTO p FROM public.notification_preferences WHERE user_id = e.recipient_id FOR UPDATE; IF NOT p.enabled OR (e.kind = 'addition' AND NOT p.additions) OR (e.kind = 'online' AND (NOT p.online OR p.last_online_notice > now() - make_interval(mins => p.online_cooldown_minutes))) OR e.created_at < now() - interval '10 minutes' THEN CONTINUE; END IF; IF e.kind = 'online' THEN UPDATE public.notification_preferences SET last_online_notice = now() WHERE user_id = e.recipient_id; END IF; RETURN NEXT e; END LOOP; END $$;
REVOKE ALL ON FUNCTION public.claim_duet_push_events() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.claim_duet_push_events() TO service_role;